using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using DogSC.Windows;
using Path=System.IO.Path;

namespace DogSC.Replica {
 public partial class Studio {
  async Task SettleEffects(){await PreviewNow();for(int i=0;i<300&&rendering;i++)await Task.Delay(50);if(rendering)throw new Exception("Effect preview did not complete");}
  public async Task VerifyEffectsInterface(string folder){try{
   await Load(Path.Combine(folder,"effects.dogscwin"));
   tab="画面";frameTab="背景";backgroundPage="图案";selectedCut=selectedZoom=selectedOverlay=-1;BuildRail();BuildInspector();var backgrounds=inspector.Children.OfType<UniformGrid>().Single();((Button)backgrounds.Children[3]).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(Doc.Style.Background!="gradient"||Doc.Style.ColorA!="#DEF2E8")throw new Exception("Background tile selection");await SettleEffects();UI.SaveImage((FrameworkElement)Window.Content,Path.Combine(Media.Root,"bin","background-preview.png"));History(false);
   backgroundPage="壁纸";BuildInspector();backgrounds=inspector.Children.OfType<UniformGrid>().Single();((Button)backgrounds.Children[0]).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(Doc.Style.Background!="image"||!File.Exists(Doc.Style.ImagePath))throw new Exception("Wallpaper tile selection");await SettleEffects();UI.SaveImage((FrameworkElement)Window.Content,Path.Combine(Media.Root,"bin","wallpaper-preview.png"));History(false);
   Find<Button>("Presets").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(50);var presets=Find<Button>("Presets").ContextMenu;if(presets==null||!presets.IsOpen)throw new Exception("Preset gallery did not open");UI.SaveImage(presets,Path.Combine(Media.Root,"bin","preset-gallery-preview.png"));var gallery=(UniformGrid)((MenuItem)presets.Items[0]).Header;((Button)gallery.Children[2]).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(presets.IsOpen||Doc.Style.Padding!=70||Doc.Style.ColorA!="#DEF2E8")throw new Exception("Preset gallery selection");History(false);
   int count=Doc.Overlays.Count;AddEffect("blur",null);if(Doc.Overlays.Count!=count+1)throw new Exception("Add softening UI action");History(false);if(Doc.Overlays.Count!=count)throw new Exception("Undo overlay");History(true);if(Doc.Overlays.Count!=count+1)throw new Exception("Redo overlay");selectedOverlay=Doc.Overlays.Count-1;Delete();if(Doc.Overlays.Count!=count)throw new Exception("Delete overlay");
   string image=Path.Combine(folder,"ui-sticker.png");File.WriteAllBytes(image,Convert.FromBase64String(Doc.Overlays.First(o=>o.Kind=="sticker").ImageData));AddEffect("sticker",image);MoveEffect("置底");if(Doc.Overlays[selectedOverlay]!=Doc.Overlays.First(o=>o.Kind=="sticker"))throw new Exception("Sticker layer controls");MoveEffect("置顶");if(Doc.Overlays[selectedOverlay]!=Doc.Overlays.Last(o=>o.Kind=="sticker"))throw new Exception("Sticker top layer");Delete();
   tab="光标";selectedCut=selectedZoom=selectedOverlay=-1;BuildRail();BuildInspector();var style=inspector.Children.OfType<ComboBox>().First();style.SelectedItem="触控圆点";if(Doc.Cursor.Asset!="dot")throw new Exception("Cursor style UI");var size=inspector.Children.OfType<Slider>().First();size.Value=2;if(Doc.Cursor.Size!=2)throw new Exception("Cursor size UI");Doc.Cursor.Asset="arrow";Doc.Cursor.ClickEffect="ripple";BuildInspector();Seek(.5);await SettleEffects();UI.SaveImage((FrameworkElement)Window.Content,Path.Combine(Media.Root,"bin","cursor-preview.png"));
   SelectEffect(Doc.Overlays.FindIndex(o=>o.Kind=="sticker"));Seek(1);await SettleEffects();var scroll=Find<ScrollViewer>("InspectorScroll");scroll.ApplyTemplate();var bar=scroll.Template.FindName("PART_VerticalScrollBar",scroll) as ScrollBar;if(bar==null||bar.ActualWidth>6)throw new Exception("Inspector scrollbar width: "+(bar==null?"missing":bar.ActualWidth+"; Width="+bar.Width+"; MinWidth="+bar.MinWidth));scroll.ScrollToVerticalOffset(200);await Task.Delay(30);if(scroll.VerticalOffset<10)throw new Exception("Inspector scrolling does not reveal lower controls");scroll.ScrollToTop();await Task.Delay(30);var grip=overlayGuides.Children.OfType<Border>().SelectMany(b=>((Grid)b.Child).Children.OfType<Thumb>()).FirstOrDefault();if(grip==null)throw new Exception("Missing canvas resize control");double oldWidth=Doc.Overlays[selectedOverlay].Width;grip.RaiseEvent(new DragStartedEventArgs(0,0));grip.RaiseEvent(new DragDeltaEventArgs(35,20));grip.RaiseEvent(new DragCompletedEventArgs(35,20,false));if(Doc.Overlays[selectedOverlay].Width<=oldWidth)throw new Exception("Canvas resize did not update sticker geometry");await SettleEffects();UI.SaveImage((FrameworkElement)Window.Content,Path.Combine(Media.Root,"bin","sticker-preview.png"));
   SelectEffect(Doc.Overlays.FindIndex(o=>o.Kind=="blur"));Seek(1);await SettleEffects();UI.SaveImage((FrameworkElement)Window.Content,Path.Combine(Media.Root,"bin","softening-preview.png"));Doc.Save(Path.Combine(folder,"ui-effects.dogscwin"));File.WriteAllText(Path.Combine(folder,"ui-results.txt"),"PASS: add/delete overlays, undo/redo, layer changes, native cursor controls, canvas resize, preview rendering, project save.\n");
  }finally{dirty=false;}}
 }
}
